    transientRetrySleeper = (delay, token) async => true;
    transientRetryNotice = null;
    transientRetryJitter = () => 0;
    transientRetryDeadlineLeft = null;
    transientRetryWrapUpMargin = const Duration(seconds: 120);
  });
