      // mid-reasoning drop leaves no trace and the retry regenerates the
      // reasoning (re-billed reasoning accepted, same as any retry).
      if (transientRetryBufferThinking) {
        run.buffer.add(event);
        return null;
      }
      run.commitWith(event);
