      final waits = <Duration>[];
      transientRetrySleeper = (delay, token) async {
        waits.add(delay);
        return true;
      };
      final wrapped = transientRetryStreamFunction((
        model,
        context, {
        cancelToken,
      }) {
        calls++;
        if (calls <= 3) {
          return failWith('429: Rate limit reached. Try again later.');
        }
        return FakeStreamFunction([
          textTurn('ok'),
