/// the aborted terminal was pushed.
Future<bool> _pauseBetweenAttempts(
  AssistantMessageEventStream out,
  Model model,
  AssistantMessage lastFailure,
  _ResumeState resume,
  CancelToken? cancelToken,
  Duration delay,
  int attempt,
  int maxAttempts,
  String reason,
) async {
