import 'dart:async';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

import '../cli/agent_cli_test_support.dart';

void main() {
  test('scratch: what the CLI display would print for 3 consecutive 429s', () async {
    final displays = <String>[];
    final records = <Map<String, Object?>>[];
    transientRetrySleeper = (delay, token) async => true;
    transientRetryNotice = (attempt, maxAttempts, delay, reason) {
      // Exactly what agent_cli_io.dart renders + records.
      displays.add(
        'retrying in ${delay.inSeconds}s (attempt ${attempt + 1}/$maxAttempts)',
      );
      records.add({'attempt': attempt, 'max_attempts': maxAttempts});
    };
    var calls = 0;
    final wrapped = transientRetryStreamFunction((model, context, {cancelToken}) {
      calls++;
      final stream = AssistantMessageEventStream();
      scheduleMicrotask(() {
        stream.push(
          ErrorEvent(
            reason: StopReason.error,
            error: AssistantMessage(
              content: const [],
              api: 'test-api',
              provider: 'test-provider',
              model: 'test-model',
              usage: Usage.zero,
              stopReason: StopReason.error,
              errorMessage: '429: Rate limit reached. Try again later.',
              timestamp: DateTime.utc(2026),
            ),
          ),
        );
        stream.end();
      });
      return stream;
    });

    final message = await wrapped(testModel, const Context(messages: [])).result;
    expect(message.stopReason, StopReason.error);
    // ignore: avoid_print
    print('DISPLAYS: $displays');
    // ignore: avoid_print
    print('RECORDS: $records');
  });
}
"}

