  if (!survived && cancelToken?.cancelReason is! RunIdleWatchdogFire) {
    _pushAborted(out, model, lastFailure, resume: resume);
    return false;
  }
  transientRetryNotice?.call(
    attempt,
    maxAttempts,
    survived ? delay : Duration.zero,
    reason,
