        'retry follows, so no `[net] rate limited` face for it', () async {
      var calls = 0;
      final notices = <String>[];
      transientRetryNotice = (attempt, maxAttempts, delay, reason) {
        notices.add('$reason in ${delay.inSeconds}s');
      };
